from re import search

from .common import WtsSimCommon
from ..exception import ProcessCannotStart, PortIsReserved


class Edaemon(WtsSimCommon):
    """A class to handle the startup/shutdown procedure for edaemon."""

    def __init__(self, ssh_client, port, *args, **kwargs):
        """
        :param SSHClient ssh_client: Connected SSH client.
        :param integer   port:       Edaemon control port.
        """
        super(Edaemon, self).__init__(*args, **kwargs)
        self._client = ssh_client
        self._port = port
        self._check_client()

    @property
    def client(self):
        """Client connected to the remote/local host

        :return: Client object
        """
        return self._client

    def setup(self, reconnect=False):
        """Clean the environment and start a new instance of edaemon if reconnect flag is not set.
           If flag is set, previous instance edaemon is not removed.

        :param bool reconnect: Allows the reuse of previously created edaemon instances if flag is set.
                               Default value is False.
        """
        if reconnect:
            self._started = True
            self._remove_old_logs()
        else:
            self._started = True
            self._kill_edaemon()
            self._remove_old_logs()
            self._start_edaemon()

    def teardown(self):
        """Clean the environment and stop an existing edaemon."""
        self._started = False
        self._kill_edaemon()

    def _kill_edaemon(self):
        if self._pid is not None:
            self._kill_process()
            self._kill_process(process_cmd=('^sim_*.*%d' % self._port))  # iphy wo
        else:
            self._kill_unknown_edaemon()
        self._pid = None

    def _kill_unknown_edaemon(self):
        self._kill_process(process_cmd='edaemon\s*--port\s*%d' % self._port)
        self._kill_process(process_cmd='^sim_*.*%d' % self._port)

    def _remove_old_logs(self):
        self._client.execute_command(r"cd {}; "
                                     r"sudo rm -rf mme*.log.*; "
                                     r"sudo rm -rf pgw*.log.*; "
                                     r"sudo rm -rf sgw*.log.*; "
                                     r"sudo rm -rf uec*.log.*".format(self._tool_dir))

    def _start_edaemon(self):
        if not self._is_tcp_port_free(self._port):
            raise PortIsReserved("Edaemon", self._port)
        if not self._pid:
            cmd = r"cd %s; sudo ./edaemon --port %s" % (self._tool_dir, self._port)
            out, err, rc = self._client.execute_command(cmd)
            self._pid = self._get_edaemon_pid(out, err)

    def _get_edaemon_pid(self, out, err):
        found = search("EDAEMON:\s*SERVER\s*PID\s*=\s*(.*)", out)
        if not found:
            raise ProcessCannotStart("Cannot start edaemon process and shell output is:", out, err)
        return found.groups()[0].strip()
